using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class SoundPathSetup{public static void Run(){EditorSceneManager.OpenScene("Assets/MusicRoom.unity");foreach(var b in Object.FindObjectsByType<MonoBehaviour>(FindObjectsInactive.Include,FindObjectsSortMode.None))if(b!=null&&!(b is UnityEngine.EventSystems.UIBehaviour)&&!(b is TMPro.TMP_Text)&&!(b is DrumRecorder)&&!(b is DrumSound))b.enabled=false;foreach(var c in Object.FindObjectsByType<Collider>(FindObjectsInactive.Include,FindObjectsSortMode.None))c.enabled=false;new GameObject("All drums sound path probe",typeof(AllDrumsPathProbe));EditorUtility.audioMasterMute=false;EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/SoundPathProbe.unity");EditorApplication.EnterPlaymode();}}
